'use strict';

/**
 * Build the GitHub Pages artifact without copying the repository.
 *
 * The source tree contains research receipts, raw responses, local ledgers and
 * runtime state.  Pages receives only the explicit list below plus the two
 * public dashboard projections generated by this file.
 */
const fs = require('fs');
const path = require('path');

const PUBLIC_FILES = Object.freeze([
  'index.html',
  'sports.html',
  'research.html',
  'number-tools.html',
  'sports-standalone.html',
  'lotto-standalone.html',
  'number-tools-standalone.html',
  'research-standalone.html',
  'manifest.json',
  'docs/testing/scientific-evaluation.json',
  'engine.js',
  'number-models.js',
  'number-settlement.js',
  'number-app.js',
  'sports-form-analyzer.js',
  'sports-jingcai-engine.js',
  'sports-sfc-engine.js',
  'sports-beidan-engine.js',
  'sports-lancai-engine.js',
  'sports-mock-data.js',
  'research-dashboard.js',
  'data/ssq-compact.js',
  'data/dlt-compact.js',
  'data/sports-live-data.js',
  'data/sports_live.json',
  'data/cloud-refresh-status.json',
  'data/numbers/public-snapshot.json',
  'returns-workbench.js',
  'sports-return-policy.js',
  'number-crowd-model.js'
]);

const DASHBOARDS = Object.freeze([
  ['data/numbers/dashboard.js', 'NUMBER_DASHBOARD'],
  ['data/research/dashboard.js', 'RESEARCH_DASHBOARD']
]);

const OPTIONAL_DASHBOARDS = Object.freeze([
  ['docs/testing/scientific-evaluation.json', null],
  ['data/returns/crowd-report.js', 'NUMBER_CROWD_REPORT'],
  ['data/returns/crowd-report.json', 'NUMBER_CROWD_REPORT']
]);

// Body hashes identify public source provenance. These fields identify local
// implementation or raw training archives and have no use on a public page.
const OMIT_KEYS = new Set([
  'rawref', 'rawbody', 'rawresponse', 'codehashes', 'protocolsha256',
  'protocolhash', 'inputsha256', 'runtimeinputhash', 'modelsha256',
  'rawarchive', 'rawarchivepath', 'localpath', 'absolutepath',
  'hash', 'sha256', 'receiptsha256', 'inputhash', 'bodyhashes', 'sourcehashes', 'archivehashes'
]);

function isLocalPath(value) {
  return typeof value === 'string' && (
    /^[a-z]:[\\/]/i.test(value) ||
    /^\\\\/.test(value) ||
    /^\/(?:users|home|private|var|tmp)\//i.test(value)
  );
}

function projectPublic(value, context = []) {
  if (isLocalPath(value)) return undefined;
  if (typeof value === 'string' && OMIT_KEYS.has(value.toLowerCase())) return undefined;
  if (Array.isArray(value)) return value.map((item, index) => projectPublic(item, context.concat(String(index)))).filter(item => item !== undefined);
  if (!value || typeof value !== 'object') return value;
  const result = {};
  for (const [key, child] of Object.entries(value)) {
    const lower = key.toLowerCase();
    if (OMIT_KEYS.has(lower)) continue;
    // These are large per-row training artifacts. The public summary retains
    // the model aggregates and the registered ticket batches instead.
    if ((lower === 'rows' || lower === 'periods') && context.includes('evaluation')) continue;
    if (lower === 'periods' && context.includes('report')) continue;
    if (lower === 'reports' && context.includes('numberTournament')) continue;
    if (lower === 'specialprizeevidence') continue;
    const projected = projectPublic(child, context.concat(key));
    if (projected !== undefined) result[key] = projected;
  }
  return result;
}

function readDashboard(filename, globalName) {
  return serializeDashboard(parseDashboard(filename, globalName), globalName);
}

function parseDashboard(filename, globalName) {
  const source = fs.readFileSync(filename, 'utf8');
  const assignment = source.indexOf(`window.${globalName}`);
  const start = source.indexOf('{', assignment < 0 ? 0 : assignment);
  const end = source.lastIndexOf('}');
  if (start < 0 || end < start) throw new Error(`Invalid dashboard script: ${filename}`);
  return projectPublic(JSON.parse(source.slice(start, end + 1)));
}

function serializeDashboard(dashboard, globalName) {
  return `window.${globalName} = ${JSON.stringify(dashboard).replace(/</g, '\\u003c')};\n`;
}

function readOptionalDashboard(filename, globalName) {
  const source = fs.readFileSync(filename, 'utf8');
  if (filename.endsWith('.json')) return `${JSON.stringify(projectPublic(JSON.parse(source)), null, 2)}\n`;
  return readDashboard(filename, globalName);
}

function mergePublicNumberSnapshot(rootDir, dashboard) {
  const snapshotFile = path.resolve(rootDir, 'data/numbers/public-snapshot.json');
  if (!fs.existsSync(snapshotFile)) return dashboard;
  const snapshot = projectPublic(JSON.parse(fs.readFileSync(snapshotFile, 'utf8')));
  const games = { ...(dashboard.games || {}) };
  const timestamp = value => {
    const parsed = Date.parse(value || '');
    return Number.isFinite(parsed) ? parsed : -Infinity;
  };
  for (const [gameId, incoming] of Object.entries(snapshot.games || {})) {
    const existing = games[gameId] || {};
    const existingAt = timestamp(existing.fetchedAt || dashboard.sourceGeneratedAt || dashboard.generatedAt);
    const incomingAt = timestamp(incoming.fetchedAt || snapshot.generatedAt);
    const incomingIsNewer = incomingAt >= existingAt;
    const byIssue = new Map();
    for (const [draw, fallbackAt] of [
      ...(existing.draws || []).map(draw => [draw, existingAt]),
      ...(incoming.draws || []).map(draw => [draw, incomingAt])
    ]) {
      const previous = byIssue.get(draw.issue);
      const observedAt = timestamp(draw.source && draw.source.fetchedAt) > -Infinity ? timestamp(draw.source.fetchedAt) : fallbackAt;
      if (!previous || observedAt >= previous.observedAt) byIssue.set(draw.issue, { draw, observedAt });
    }
    const merged = incomingIsNewer ? { ...existing, ...incoming } : { ...incoming, ...existing };
    games[gameId] = { ...merged, draws: [...byIssue.values()].map(item => item.draw).sort((a, b) => String(a.date).localeCompare(String(b.date))) };
  }
  return { ...dashboard, games, cloudRefresh: { generatedAt: snapshot.generatedAt, status: snapshot.status, evidence: snapshot.evidence } };
}

function assertInside(root, candidate) {
  const relative = path.relative(root, candidate);
  if (relative.startsWith('..') || path.isAbsolute(relative)) throw new Error(`Path escapes project root: ${candidate}`);
}

function copyIfPresent(rootDir, outDir, relative) {
  const source = path.resolve(rootDir, relative);
  assertInside(path.resolve(rootDir), source);
  if (!fs.existsSync(source)) return false;
  const target = path.resolve(outDir, relative);
  assertInside(path.resolve(outDir), target);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  if (relative === 'index.html') {
    let html = fs.readFileSync(source, 'utf8');
    if (!html.includes('window.NUMBER_APP_OFFLINE')) html = html.replace('<head>', '<head>\n<script>window.NUMBER_APP_OFFLINE = true;</script>');
    fs.writeFileSync(target, html, 'utf8');
  } else fs.copyFileSync(source, target);
  return true;
}

function replaceEmbeddedObject(html, globalName, replacement) {
  const marker = `window.${globalName}`;
  const markerAt = html.indexOf(marker);
  if (markerAt < 0) return html;
  const objectStart = html.indexOf('{', markerAt);
  if (objectStart < 0) return html;
  let depth = 0; let quoted = false; let escaped = false;
  for (let index = objectStart; index < html.length; index += 1) {
    const character = html[index];
    if (quoted) {
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === '"') quoted = false;
      continue;
    }
    if (character === '"') { quoted = true; continue; }
    if (character === '{') depth += 1;
    else if (character === '}' && --depth === 0) return html.slice(0, objectStart) + replacement + html.slice(index + 1);
  }
  throw new Error(`Unclosed embedded ${globalName} object`);
}

function copyStandalone(rootDir, outDir, relative) {
  const source = path.resolve(rootDir, relative);
  if (!fs.existsSync(source)) return false;
  let html = fs.readFileSync(source, 'utf8');
  for (const [dashboard, globalName] of DASHBOARDS) {
    const dashboardFile = path.resolve(rootDir, dashboard);
    if (fs.existsSync(dashboardFile)) {
      let projected = parseDashboard(dashboardFile, globalName);
      if (globalName === 'NUMBER_DASHBOARD') projected = mergePublicNumberSnapshot(rootDir, projected);
      html = replaceEmbeddedObject(html, globalName, JSON.stringify(projected).replace(/</g, '\\u003c'));
    }
  }
  const crowd = path.resolve(rootDir, 'data/returns/crowd-report.js');
  if (fs.existsSync(crowd)) html = replaceEmbeddedObject(html, 'NUMBER_CROWD_REPORT', readDashboard(crowd, 'NUMBER_CROWD_REPORT').replace('window.NUMBER_CROWD_REPORT = ', '').trim().replace(/;$/, ''));
  const target = path.resolve(outDir, relative);
  assertInside(path.resolve(outDir), target);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, html, 'utf8');
  return true;
}

function buildPublicSite({ rootDir = path.resolve(__dirname, '..'), outDir = path.join(rootDir, 'dist-public') } = {}) {
  const root = path.resolve(rootDir);
  const output = path.resolve(outDir);
  assertInside(root, output);
  if (output === root) throw new Error('Public output cannot be the project root');
  fs.rmSync(output, { recursive: true, force: true });
  fs.mkdirSync(output, { recursive: true });

  const copied = [];
  for (const relative of PUBLIC_FILES) {
    if (relative.endsWith('-standalone.html')) {
      if (copyStandalone(root, output, relative)) copied.push(relative);
    } else if (copyIfPresent(root, output, relative)) copied.push(relative);
  }
  for (const [relative, globalName] of DASHBOARDS) {
    const source = path.resolve(root, relative);
    if (!fs.existsSync(source)) throw new Error(`Required dashboard is missing: ${relative}`);
    const target = path.resolve(output, relative);
    assertInside(output, target);
    fs.mkdirSync(path.dirname(target), { recursive: true });
    let dashboard = parseDashboard(source, globalName);
    if (relative === 'data/numbers/dashboard.js') dashboard = mergePublicNumberSnapshot(root, dashboard);
    fs.writeFileSync(target, serializeDashboard(dashboard, globalName), 'utf8');
    copied.push(relative);
  }
  for (const [relative, globalName] of OPTIONAL_DASHBOARDS) {
    const source = path.resolve(root, relative);
    if (!fs.existsSync(source)) continue;
    const target = path.resolve(output, relative);
    assertInside(output, target);
    fs.mkdirSync(path.dirname(target), { recursive: true });
    fs.writeFileSync(target, readOptionalDashboard(source, globalName), 'utf8');
    copied.push(relative);
  }

  // A Pages artifact must never contain an unlisted file. This check also
  // catches stale files if a caller supplies an existing output directory.
  const actual = [];
  function walk(directory) {
    for (const entry of fs.readdirSync(directory, { withFileTypes: true })) {
      const full = path.join(directory, entry.name);
      if (entry.isDirectory()) walk(full);
      else actual.push(path.relative(output, full).replaceAll(path.sep, '/'));
    }
  }
  walk(output);
  const allowed = new Set([...PUBLIC_FILES, ...DASHBOARDS.map(item => item[0]), ...OPTIONAL_DASHBOARDS.map(item => item[0])].filter(relative => fs.existsSync(path.resolve(root, relative)) || DASHBOARDS.some(item => item[0] === relative)));
  const unexpected = actual.filter(relative => !allowed.has(relative));
  if (unexpected.length) throw new Error(`Unexpected public files: ${unexpected.join(', ')}`);
  return { outDir: output, files: actual.sort(), copied: copied.sort() };
}

if (require.main === module) {
  try {
    const result = buildPublicSite();
    console.log(`Built ${result.files.length} public files in ${result.outDir}`);
  } catch (error) {
    console.error(error.stack || error.message);
    process.exitCode = 1;
  }
}

module.exports = { PUBLIC_FILES, DASHBOARDS, OPTIONAL_DASHBOARDS, OMIT_KEYS, projectPublic, readDashboard, parseDashboard, mergePublicNumberSnapshot, buildPublicSite };
